namespace ghidra.app.plugin.core.function.editor;









using docking;
using generic.theme.GThemeDefaults.Colors;
using ghidra.program.model.listing;

class StorageTableCellEditor : AbstractCellEditor, TableCellEditor {

	private VariableStorage storage;
	private FunctionEditorModel model;

	public StorageTableCellEditor(FunctionEditorModel model) {
		this.model = model;
	}

	/* @Override */
	public object getCellEditorValue() {
		return storage;
	}

	/* @Override */
	public bool isCellEditable(EventObject e) {
		if (e is MouseEvent) {
			return ((MouseEvent) e).getClickCount() > 1;
		}
		return true;
	}

	/* @Override */
	public Component getTableCellEditorComponent(JTable table, object value,
			bool isSelected, int row, int column) {

		storage = null;
		string stringValue = value == null ? "" : value.toString();
		JTextField field = new JTextField(stringValue);
		field.setBackground(getUneditableForegroundColor(isSelected));
		field.setEditable(false);
		field.setBorder(null);
		ParameterTableModel tableModel = (ParameterTableModel) table.getModel();
		FunctionVariableData rowData = tableModel.getRowObject(row);
		StorageAddressEditorDialog dialog = new StorageAddressEditorDialog(model.getProgram(),
			model.getDataTypeManagerService(), (VariableStorage) value, rowData);
		SwingUtilities.invokeLater(() => {
			DockingWindowManager.showDialog(table, dialog);
			if (!dialog.wasCancelled()) {
				storage = dialog.getStorage();
			}
			TableCellEditor cellEditor = table.getCellEditor();
			if (cellEditor == null) {
				return;
			}
			if (storage == null) {
				cellEditor.cancelCellEditing();
			}
			else {
				cellEditor.stopCellEditing();
			}
		});
		return field;
	}

	protected Color getUneditableForegroundColor(bool isSelected) {
		return isSelected ? Tables.UNEDITABLE_SELECTED : Tables.UNEDITABLE_UNSELECTED;
	}

}
